class Solution {
public:
    long long minDamage(int power, vector<int>& damage, vector<int>& health) {
        int n = damage.size();
        vector<int> turns(n);
        for (int i = 0; i < n; ++i) {
            turns[i] = (health[i] + power - 1) / power;
        }
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int i, int j) {
            return 1LL * damage[i] * turns[j] > 1LL * damage[j] * turns[i];
        });

        long long total_damage = 0;
        long long total_d = 0;
        for (int d : damage) total_d += d;
        for (int idx : order) {
            total_damage += total_d * turns[idx];
            total_d -= damage[idx];
        }
        return total_damage;
    }
};

class Solution {
    public long minDamage(int power, int[] damage, int[] health) {
        int n = damage.length;
        int[] turns = new int[n];
        for (int i = 0; i < n; ++i) {
            turns[i] = (health[i] + power - 1) / power;
        }
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; ++i) order[i] = i;
        Arrays.sort(order, (i, j) -> {
            long val1 = (long) damage[i] * turns[j];
            long val2 = (long) damage[j] * turns[i];
            return Long.compare(val2, val1);
        });

        long totalDamage = 0;
        long totalD = 0;
        for (int d : damage) totalD += d;
        for (int idx : order) {
            totalDamage += totalD * turns[idx];
            totalD -= damage[idx];
        }
        return totalDamage;
    }
}

var minDamage = function(power, damage, health) {
    const n = damage.length;
    const turns = health.map(h => Math.ceil(h / power));
    const order = Array.from({ length: n }, (_, i) => i);
    order.sort((i, j) => {
        const val1 = BigInt(damage[i]) * BigInt(turns[j]);
        const val2 = BigInt(damage[j]) * BigInt(turns[i]);
        return val1 > val2 ? -1 : val1 < val2 ? 1 : 0;
    });

    let totalDamage = 0n;
    let totalD = damage.reduce((acc, d) => acc + BigInt(d), 0n);
    for (const idx of order) {
        totalDamage += totalD * BigInt(turns[idx]);
        totalD -= BigInt(damage[idx]);
    }
    return Number(totalDamage);
};
